from html.parser import HTMLParser

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.self_closing = {'img', 'meta', 'link', 'br', 'hr', 'input'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.self_closing:
            self.tags.append(tag)
    def handle_endtag(self, tag):
        if tag not in self.self_closing:
            if not self.tags:
                print('Unexpected end tag:', tag)
            else:
                last = self.tags.pop()
                if last != tag:
                    print(f'Mismatched tag: expected {last}, got {tag}')

v = Validator()
with open('C:/RL Multimodal/RL_Multimodal/RL Multimodal_BrightSmile Dental/Gemini_BrightSmile Dental/index.html', 'r', encoding='utf-8') as f:
    v.feed(f.read())
if v.tags:
    print('Unclosed tags:', v.tags)
else:
    print('HTML tag matching: SUCCESS')
"

